spec.model = (function()
  --[[ Popup overlay screens - shared declarations.
  
  The shared Popup overlay (src/skins/Popup.skin.js) hosts the stock FC modal and a set of full screens. The model of the
  overlay is built from several files, joined in order into one chunk by skinc:
  
    modes.lua        this file: the MODES registry and small helpers
    slots.lua        the save-slot screen            (FCPopup:showSlots,                PrismSlots.pick)
    academy.lua      the youth academy               (FCPopup:showScreen("academy"),    PrismYouth.openAcademy)
    setup.lua        the new-career setup screen     (FCPopup:showScreen("setup"),      PrismSetup.open)
    history.lua      the transfer history            (FCPopup:showScreen("history"),    PrismHistory.open)
    profile.lua      the player profile              (FCPopup:showScreen("profile"),    PrismProfile.open)
    training.lua     the weekly training (R98e)      (FCPopup:showTraining,             PrismTraining.open)
    Popup.model.lua  the dispatcher (returned to PrismSkin as the model)
  
  A mode registers MODES.<name> = { on = "<binding>", run = function(s, o, data, pub) ... end }. FCPopup hands the screen's
  spec over as popupData[<name>]; the dispatcher publishes every mode's `on` binding (true only for the active one) and calls
  the active mode's run(s, o, data, pub), where:
  
    s      the PrismSkin session (s.handlers: action name -> function; s:onPublish(binding, value))
    o      the stock Popup VM (o:_clickEvent(n) answers the opener and closes the overlay)
    data   the spec table the opener passed
    pub    pub(binding, value) - publish a value to the native screen
  
  Each mode file wraps its locals in do ... end: the joined chunk is one Lua function, and Lua 5.1 allows 200 locals in it.
  ]]
  local MODES = {}
  local MODE_ORDER = { "slots", "academy", "setup", "history", "profile", "training" }
  
  --- tostring that maps nil to ""
  local function str(v) return v == nil and "" or tostring(v) end
  
  --- Answers the opener once: the overlay closes and the opener's callback receives n.
  local function answerOnce(o)
    local answered = false
    return function(n)
      if answered or type(o._clickEvent) ~= "function" then return end
      answered = true
      o:_clickEvent(n)
    end
  end
  
  --[[ Save-slot screen (FC "Load / Save Career").
  
  PrismSlots.pick builds the cards (src/career/PrismSlots.lua) and opens the overlay through FCPopup:showSlots. The model
  publishes one card per slot and the selection. A tap selects a card; the CTA under the selected card answers 100 + its
  slot number; Back answers 0. A card with nothing to do (an empty slot on the Load screen) says so in the hint line.
  ]]
  do
    local N = 15
    MODES.slots = { on = "bnd_slots_on", run = function(s, o, sp, pub)
      local cards = type(sp.cards) == "table" and sp.cards or {}
      local sel = tonumber(sp.sel) or 0
      pub("bnd_slots_title", str(sp.title))
      pub("bnd_slots_hint", str(sp.hint))
      pub("bnd_slots_free", str(sp.free or 0))
      for n = 1, N do
        local c = cards[n] or {}
        pub("bnd_slotvis" .. n, cards[n] ~= nil)   -- the build's slot count (PrismSlots.COUNT: pt-BR has 10 of the 15 cards)
        pub("bnd_slotused" .. n, c.used and true or false)
        pub("bnd_slottitle" .. n, str(c.title))
        pub("bnd_slotsub" .. n, str(c.sub))
        pub("bnd_slotdesc" .. n, str(c.desc))
        pub("bnd_slotfull" .. n, str(c.full))
        pub("bnd_slotmodeline" .. n, str(c.modeLine))
        pub("bnd_slotmode" .. n, str(c.mode))
        pub("bnd_slotcrest" .. n, c.crest or {})
        pub("bnd_slotnext" .. n, c.hasNext and true or false)
        pub("bnd_slotleague" .. n, c.league or {})
        pub("bnd_slothome" .. n, c.home or {})
        pub("bnd_slotaway" .. n, c.away or {})
        pub("bnd_slotdate" .. n, str(c.date))
        pub("bnd_slotcta" .. n, str(c.cta))
        pub("bnd_slotctavis" .. n, c.cta ~= nil and c.cta ~= "")
      end
      pub("bnd_slotsel", sel)
      local answer = answerOnce(o)
      local H = s.handlers
      local function say(n)
        local c = cards[n]
        if c and not (c.cta and c.cta ~= "") then pub("bnd_slots_hint", "Slot " .. n .. " is empty. Pick a saved career to load it.")
        else pub("bnd_slots_hint", str(sp.hint)) end
      end
      for n = 1, N do H["act_slot" .. n] = function() sel = n; pub("bnd_slotsel", sel); say(n) end end
      H.act_slot_go = function() local c = cards[sel]; if c and c.cta and c.cta ~= "" then answer(100 + sel) else say(sel) end end
      H.act_slot_back = function() answer(0) end
      return true
    end }
  end
  
  --[[ Youth academy screen.
  
  PrismYouth.openAcademy opens it. Up to twenty prospect cards are read live from PrismYouth.academy(). The selected one is
  promoted to the first team (CTA) or released into the youth pool (footer) in place: the cards are published again and
  nothing closes. Back closes the screen.
  ]]
  do
    local NA = 20
    MODES.academy = { on = "bnd_acad_on", run = function(s, o, ac, pub)
      local Y = rawget(_G, "PrismYouth")
      local list, sel = {}, 0
      local function refresh(hint)
        list = (Y and Y.academy and Y.academy()) or {}
        if sel > #list then sel = #list end
        if sel == 0 and #list > 0 then sel = 1 end
        pub("bnd_acad_title", str(ac.title or "Youth Academy"))
        pub("bnd_acad_hint", str(hint or ac.hint))
        pub("bnd_acad_count", tostring(#list) .. " / " .. tostring((Y and Y.CFG and Y.CFG.ACADEMY) or NA))
        for n = 1, NA do
          local c = list[n]
          pub("bnd_acadvis" .. n, c ~= nil)
          pub("bnd_acadtitle" .. n, c and str(c.name) or "")
          pub("bnd_acadsub" .. n, c and str(c.pos) or "")
          pub("bnd_acadline" .. n, c and str(c.line) or "")
          pub("bnd_acadage" .. n, c and ("Age " .. str(c.age)) or "")
          pub("bnd_acadovr" .. n, c and str(c.ovr) or "")
          pub("bnd_acadpot" .. n, c and str(c.pot) or "")
        end
        pub("bnd_acadsel", sel)
      end
      refresh()
      local answer = answerOnce(o)
      local H = s.handlers
      for n = 1, NA do H["act_acad" .. n] = function() if list[n] then sel = n; pub("bnd_acadsel", sel) end end end
      H.act_acad_go = function()
        local c = list[sel]
        if c and Y and Y.promote and Y.promote(c.id) then refresh(c.name .. " joins your first team.")
        elseif c then refresh("Could not promote " .. c.name .. ".") end
      end
      H.act_acad_release = function()
        local c = list[sel]
        if c and Y and Y.release and Y.release(c.id) then refresh(c.name .. " has left the academy.") end
      end
      H.act_acad_back = function() answer(0) end
      return true
    end }
  end
  
  --[[ Career Setup screen.
  
  PrismSetup.open opens it from the team picker with spec = { choices = <current settings>, api = <engine api> }. Four tabs
  of settings (see src/career/PrismSetup.lua for what each one drives); a tap on a row focuses it, the arrows change its
  value. Start Career writes the choices to spec.result and answers 100; Back answers 0 (the team picker stays); Restore
  Defaults puts every setting back to the game's normal behaviour.
  ]]
  do
    local N = 4
    local function onOff(on, off) return { { "On", true, on }, { "Off", false, off } } end
    local function pct(list)
      local out = {}
      for _, e in ipairs(list) do out[#out + 1] = { e[2], e[1], e[3] } end
      return out
    end
    -- every setting: label, description, values { text, value, description of that value? }
    local DEF = {
      ucl = { "Champions League", "A league of 20 clubs and 38 Tuesday matchdays: the top four of England, France, Germany, Italy and Spain, and the holder. Off: no European football.",
        onOff() },
      friendlies = { "Pre-season League", "A league of 36 clubs played every day from 1 June to 9 August, 70 matches. Off: no pre-season.", onOff() },
      worldcup = { "World Cup", "Every four years the World Cup is played in June, with its international call-ups. Off: no World Cup and no call-ups.",
        onOff() },
      grow = { "Player Growth", "How fast players improve towards their potential. Potential stays the ceiling: faster growth only gets there sooner.",
        pct({ { 50, "Very Slow" }, { 75, "Slow" }, { 100, "Normal" }, { 150, "Fast" }, { 200, "Very Fast" } }) },
      decline = { "Player Decline", "How fast players lose ability once they are past their peak (about 30, keepers later).",
        pct({ { 50, "Very Slow" }, { 75, "Slow" }, { 100, "Normal" }, { 150, "Fast" }, { 200, "Very Fast" } }) },
      retire = { "Retirement Age", "When players hang up their boots. Retired players are replaced by youth players across the world.",
        pct({ { -2, "Much Earlier" }, { -1, "Earlier" }, { 0, "Normal" }, { 1, "Later" }, { 2, "Much Later" } }) },
      funds = { "Transfer Budget", "How generous the board is with your transfer budget each season, compared with the budget your club's level earns.",
        pct({ { 50, "Strict (50%)" }, { 75, "Tight (75%)" }, { 100, "Normal" }, { 150, "Generous (150%)" }, { 200, "Lavish (200%)" }, { 300, "Unlimited (£1B)" } }) },
      market = { "Transfer Market", "How busy the AI clubs are in the transfer windows, buying from each other and bidding for your players. Off: no AI transfers at all.",
        pct({ { 0, "Off" }, { 50, "Quiet" }, { 100, "Normal" }, { 150, "Busy" }, { 200, "Very Busy" } }) },
      difficulty = { "Difficulty", "The match difficulty while you play this career. Your usual setting comes back when you leave the career.", nil },
      autosave = { "Autosave", "Save the career automatically after each of your matches and at the start of every month.", onOff() },
      slot = { "Save Slot", "The slot this career saves into, autosave included. Auto takes the first free slot when the career is first saved.", nil },
    }
    local TABS = {
      { "Competitions", { "ucl", "friendlies" } },
      { "Players", { "grow", "decline", "retire" } },
      { "Club", { "funds", "market", "difficulty" } },
      { "Saving", { "autosave", "slot" } },
    }
  
    -- The same screen with another set of rows (Player Career's Create Your Player, PrismPro.open): spec.def / spec.tabs
    -- / spec.defaults replace the career settings; spec.title / spec.go / spec.reset are the header and the two button
    -- texts; spec.describe(key, choices) -> title, text replaces a row's description; spec.onChange(choices, key) runs
    -- after every change (the 3D preview); spec.pro shows the narrow info panel and the 3D model's place (slot 4).
    MODES.setup = { on = "bnd_cs_on", run = function(s, o, spec, pub)
      local DEF = type(spec.def) == "table" and spec.def or DEF
      local TABS = type(spec.tabs) == "table" and spec.tabs or TABS
      local P = rawget(_G, "PrismSetup")
      local defaults = (type(spec.defaults) == "table" and spec.defaults) or (P and P.DEFAULTS) or {}
      local choices = {}
      for k, v in pairs(defaults) do choices[k] = v end
      for k, v in pairs(type(spec.choices) == "table" and spec.choices or {}) do choices[k] = v end
  
      -- values that depend on the game: its difficulty levels, the free save slots
      local values = {}
      for k, d in pairs(DEF) do values[k] = d[3] end
      local levels, current
      if P and P.difficultyLevels then levels, current = P.difficultyLevels(spec.api) end
      if levels then
        values.difficulty = { { "Game Setting", nil } }
        for _, l in ipairs(levels) do values.difficulty[#values.difficulty + 1] = { l.name, l.value } end
        if current ~= nil then for _, l in ipairs(levels) do if l.value == current then values.difficulty[1][1] = "Game Setting (" .. l.name .. ")" end end end
      end
      local PS = rawget(_G, "PrismSlots")
      values.slot = { { "Auto", 0 } }
      if PS and PS.isFree and PS.COUNT then
        for n = 1, PS.COUNT do local okF, free = pcall(PS.isFree, n); if okF and free then values.slot[#values.slot + 1] = { "Slot " .. n .. " (empty)", n } end end
      end
  
      local tabs = {}
      for _, t in ipairs(TABS) do
        local keys = {}
        for _, k in ipairs(t[2]) do if values[k] then keys[#keys + 1] = k end end
        tabs[#tabs + 1] = { name = t[1], keys = keys }
      end
      local tab, sel = 1, 1
      local function idxOf(k)
        local list = values[k]
        for i, e in ipairs(list) do if e[2] == choices[k] then return i end end
        for i, e in ipairs(list) do if e[2] == defaults[k] then return i end end
        return 1
      end
      local function publish()
        local t = tabs[tab]
        for k = 1, 4 do pub("bnd_cs_tn" .. k, tabs[k] and tabs[k].name or "") end
        pub("bnd_cs_tab", tab)
        pub("bnd_cs_n", #t.keys)
        if sel > #t.keys then sel = #t.keys end
        if sel < 1 then sel = 1 end
        pub("bnd_cs_sel", sel)
        for k = 1, N do
          local key = t.keys[k]
          pub("bnd_cs_l" .. k, key and DEF[key][1] or "")
          pub("bnd_cs_v" .. k, key and values[key][idxOf(key)][1] or "")
        end
        local key = t.keys[sel]
        local title, desc = key and DEF[key][1] or "", key and DEF[key][2] or ""
        if key and type(spec.describe) == "function" then
          local okD, t2, d2 = pcall(spec.describe, key, choices)
          if okD then title, desc = t2 or title, d2 or desc end
        end
        pub("bnd_cs_title", title)
        pub("bnd_cs_desc", desc)
        pub("bnd_cs_club", str(spec.club))
        pub("bnd_cs_hdr", str(spec.title or "Career Setup"))
        pub("bnd_cs_go", str(spec.go or "Start Career"))
        pub("bnd_cs_rst", str(spec.reset or "Restore Defaults"))
        pub("bnd_cs_pro", spec.pro and true or false)
        pub("bnd_cs_std", not spec.pro)
      end
      local function changed(key)
        if type(spec.onChange) == "function" then pcall(spec.onChange, choices, key) end
      end
      publish()
      changed(nil)
  
      local answer = answerOnce(o)
      local H = s.handlers
      local function step(d)
        local key = tabs[tab].keys[sel]
        if not key then return end
        local list = values[key]
        local i = idxOf(key) + d
        if i < 1 then i = #list elseif i > #list then i = 1 end
        choices[key] = list[i][2]
        changed(key)
        publish()
      end
      for k = 1, 4 do H["act_cs_tab" .. k] = function() if tabs[k] then tab, sel = k, 1; publish() end end end
      for k = 1, N do H["act_cs_row" .. k] = function() if tabs[tab].keys[k] then sel = k; publish() end end end
      H.act_cs_prev = function() step(-1) end
      H.act_cs_next = function() step(1) end
      H.act_cs_reset = function()
        choices = {}
        for k, v in pairs(defaults) do choices[k] = v end
        changed(nil)
        publish()
      end
      H.act_cs_start = function()
        local out = {}
        for k in pairs(DEF) do out[k] = choices[k] end
        spec.result = out
        answer(100)
      end
      H.act_cs_back = function() answer(0) end
      return true
    end }
  end
  
  --[[ Transfer history screen.
  
  PrismHistory.open (the hub's Transfer History card) opens it; the spec carries the hub's localiser (spec.loc) for the club
  names. The moves are read live from the career's log (PrismHistory.query): a season (newest first by default; only
  seasons that have records), a filter that cycles All / My Club / Loans, and the table of that season's moves, newest first.
  Changing the season or the filter publishes the table again; nothing closes. Back closes the screen.
  
  The league-wide lists are capped (PrismHistory.CAP rows, the biggest fees); the hint line under the table says so.
  ]]
  do
    local FILTERS = { "all", "mine", "loans" }
    MODES.history = { on = "bnd_hist_on", run = function(s, o, hs, pub)
      local H = rawget(_G, "PrismHistory")
      local sv = hs.sv   -- the career's store; nil: PrismHistory finds it
      local loc = hs.loc
      local names = {}
      local seasons, si, fi = {}, 1, 1
  
      -- a club's short name through the game's localiser ("TeamName_Abbr15_<id>"), remembered for the open screen
      local function clubName(id)
        local n = names[id]
        if n == nil then
          n = ""
          if loc and loc.LocalizeString then
            local ok, v = pcall(loc.LocalizeString, "TeamName_Abbr15_" .. tostring(id))
            if ok and type(v) == "string" and v ~= "" and not v:find("^TeamName_") then n = v end
          end
          if n == "" then n = "Club " .. tostring(id) end
          names[id] = n
        end
        return n
      end
  
      local function plural(n, one, many) return tostring(n) .. " " .. (n == 1 and one or many) end
  
      local function refresh()
        seasons = (H and H.seasons(sv)) or {}
        if si > #seasons then si = #seasons end
        if si < 1 then si = 1 end
        local season = seasons[si]
        local filter = FILTERS[fi]
        local rows, total = {}, 0
        if H and season then rows, total = H.query(sv, season, filter) end
        -- a past season keeps only what its lists show, so its league-wide total is not known
        local past = H and season and H.isPast and H.isPast(sv, season) and filter ~= "mine"
        local list = {}
        for k = 1, #rows do
          local r = rows[k]
          list[k] = { data = {
            name = r.n or ("Player " .. tostring(r.p)),
            from = clubName(r.a), fromCrest = { name = "$Crest64x64", id = r.a },
            to = clubName(r.b), toCrest = { name = "$Crest64x64", id = r.b },
            fee = H.feeText(r), date = H.dateText(r.d), mine = r.u == 1,
          } }
        end
        local label = season and H.seasonLabel(season) or "-"
        local hint
        if not season then
          hint = "No transfers have been made in this career yet."
        elseif filter == "mine" then
          hint = total == 0 and ("Your club made no moves in " .. label .. ".")
            or (plural(total, "move", "moves") .. " involving your club in " .. label .. ".")
        elseif past and filter == "loans" then
          hint = "The " .. plural(#rows, "most recent loan or return", "most recent loans and returns") .. " of " .. label .. "."
        elseif past then
          hint = "The " .. plural(#rows, "biggest-fee move", "biggest-fee moves") .. " of " .. label .. "."
        elseif filter == "loans" then
          hint = total > #rows and ("Showing the " .. #rows .. " most recent of " .. total .. " loans and returns in " .. label .. ".")
            or (plural(total, "loan or return", "loans and returns") .. " in " .. label .. ".")
        else
          hint = total > #rows and ("Showing the " .. #rows .. " biggest-fee moves of " .. total .. " in " .. label .. ".")
            or (plural(total, "move", "moves") .. " in " .. label .. ".")
        end
        if season and filter ~= "mine" and H and season <= seasons[1] - H.KEEP_SEASONS then
          hint = "Older seasons keep only your club's moves. " .. hint
        end
        pub("bnd_hist_title", tostring(hs.title or "Transfer History"))
        pub("bnd_hist_season", label)
        pub("bnd_hist_filter", (H and H.FILTER_NAMES[filter]) or filter)
        pub("bnd_hist_hint", hint)
        pub("bnd_hist_n", #list)
        pub("bnd_hist_hasprev", si < #seasons)   -- an older season exists
        pub("bnd_hist_hasnext", si > 1)          -- a newer one
        pub("bnd_hist_list", list)
      end
      refresh()
      local answer = answerOnce(o)
      local Hd = s.handlers
      Hd.act_hist_prev = function() if si < #seasons then si = si + 1; refresh() end end
      Hd.act_hist_next = function() if si > 1 then si = si - 1; refresh() end end
      Hd.act_hist_fprev = function() fi = (fi + #FILTERS - 2) % #FILTERS + 1; refresh() end
      Hd.act_hist_fnext = function() fi = fi % #FILTERS + 1; refresh() end
      Hd.act_hist_back = function() answer(0) end
      return true
    end }
  end
  
  --[[ Player Profile screen.
  
  PrismProfile.open (src/career/PrismProfile.lua) opens it with the ids of the squad being looked at and the one to show
  first. The model builds the profile of the current player (PrismProfile.get, cached while the screen is open) and
  publishes it for the three tabs - Overview, Attributes, Stats - in one pass. The Overview has two pages: the player's facts
  and the rating he has at each position on a pitch (the game's own formula, PrismProfile.build's posRatings; not for a keeper).
  Previous / Next page through the ids and publish again in place; the tab and the page stay. The player's 3D model lives in its own slot and is shown on the Overview tab only;
  Back hides it, releases the slot and answers 0.
  
  Spec (popupData.profile): { title, ids = { player ids }, index, teamId, loc, svc }.
  ]]
  do
    local COLS = { { 1, 2 }, { 3, 4 }, { 5, 6 }, { 7 } }   -- attribute groups per column of the Attributes tab
    local GK_GROUP = 7
  
    MODES.profile = { on = "bnd_pf_on", run = function(s, o, sp, pub)
      local PP = rawget(_G, "PrismProfile")
      local H = s.handlers
      local answer = answerOnce(o)
      local ids = type(sp.ids) == "table" and sp.ids or {}
      local n = #ids
      local idx = math.max(1, math.min(n, tonumber(sp.index) or 1))
      local tab, page = 1, 1
      local P
  
      local function close()
        if PP and PP.hide3d then pcall(PP.hide3d) end
        answer(0)
      end
      H.act_pf_back = close
      pub("bnd_pf_title", str(sp.title or "Player Profile"))
      pub("bnd_pf_tab", tab)
      pub("bnd_pf_page", page)
      pub("bnd_pf_pitch", false)
      if not PP or n == 0 then
        pub("bnd_pf_name", "No player")
        pub("bnd_pf_multi", false)
        return true
      end
  
      local opts = { loc = sp.loc, svc = sp.svc }
      local function bar(v, lo, hi) return math.max(0, math.min(1, (v - lo) / (hi - lo))) end
  
      local function publishOverview()
        pub("bnd_pf_name", str(P.name))
        pub("bnd_pf_first", str(P.first))
        pub("bnd_pf_last", str(P.last))
        pub("bnd_pf_ovr", str(P.ovr))
        pub("bnd_pf_ovrd", PP.deltaText(P.ovrDelta))
        pub("bnd_pf_ovrdc", PP.deltaColor(P.ovrDelta))
        pub("bnd_pf_ovrdir", PP.deltaDir(P.ovrDelta))   -- the development arrow (R98e)
        pub("bnd_pf_pos", str(P.pos))
        pub("bnd_pf_posa", str(P.positions[2]))
        pub("bnd_pf_posb", str(P.positions[3]))
        local pl = {}
        for i = 1, math.min(#P.positions, 3) do if P.positions[i] ~= "" then pl[#pl + 1] = P.positions[i] end end
        pub("bnd_pf_posline", table.concat(pl, "  \194\183  "))
        pub("bnd_pf_flag", { name = "$Flag128x128", id = P.natId or 0 })
        pub("bnd_pf_nat", str(P.nat))
        pub("bnd_pf_head", { name = "$Head", id = P.id })
        pub("bnd_pf_crest", { name = "$Crest", id = P.clubId or 0 })
        pub("bnd_pf_club", str(P.club))
        pub("bnd_pf_loan", P.loan and ("On loan from " .. str(P.loan.from) .. (P.loan.untilText and (" until " .. P.loan.untilText) or "")) or "")
        pub("bnd_pf_num", P.number and ("#" .. P.number) or "")
        pub("bnd_pf_age", P.age and tostring(P.age) or "")
        pub("bnd_pf_dob", P.dob and ("(" .. P.dob .. ")") or "")
        pub("bnd_pf_ht", P.heightCm and (P.heightCm .. " cm   " .. str(P.heightFt)) or "")
        pub("bnd_pf_wt", P.weightKg and (P.weightKg .. " kg   " .. P.weightLbs .. " lbs") or "")
        -- FC's one-line form: 6'2" / 176 lbs
        local hw = {}
        if P.heightCm then hw[#hw + 1] = str(P.heightFt) end
        if P.weightKg then hw[#hw + 1] = P.weightLbs .. " lbs" end
        pub("bnd_pf_hw", table.concat(hw, "  /  "))
        pub("bnd_pf_pot", str(P.pot))
        pub("bnd_pf_potp", (P.ovr and P.pot and P.pot > 0) and bar(P.ovr, 0, P.pot) or 0)
        pub("bnd_pf_form", str(P.form.label))
        pub("bnd_pf_formc", str(P.form.color))
        pub("bnd_pf_formp", P.form.pct)
        pub("bnd_pf_cond", str(P.cond.text))
        pub("bnd_pf_condd", str(P.cond.detail))
        pub("bnd_pf_condc", P.cond.kind == "fit" and "#43D97F" or "#F0504F")
        pub("bnd_pf_foot", str(P.foot))
        pub("bnd_pf_wf", P.weakFoot or 0)
        pub("bnd_pf_sm", P.skillMoves or 0)
        for k = 1, 6 do
          local f = P.faces[k]
          pub("bnd_pf_fl" .. k, str(f.label))
          pub("bnd_pf_fv" .. k, str(f.value))
          pub("bnd_pf_fvc" .. k, PP.tierColor(f.value))
          pub("bnd_pf_fd" .. k, PP.deltaText(f.delta))
          pub("bnd_pf_fdc" .. k, PP.deltaColor(f.delta))
          pub("bnd_pf_fdir" .. k, PP.deltaDir(f.delta))
        end
      end
  
      -- the pitch page: the rating at each position (PP.TILES order), the player's own positions in green
      local function publishPitch()
        local pr = P.posRatings
        local rows = {}
        for k = 1, #PP.TILES do
          local r = pr and pr[k]
          pub("bnd_pf_pr" .. k, r and tostring(r.value) or "")
          pub("bnd_pf_prc" .. k, (r and r.natural) and "#43D97F" or "#FFFFFF")
          if r then rows[#rows + 1] = r end
        end
        table.sort(rows, function(a, b) if a.value ~= b.value then return a.value > b.value end return a.tile < b.tile end)
        local best = {}
        for i = 1, math.min(5, #rows) do
          best[i] = { data = { pos = rows[i].tile, v = tostring(rows[i].value), c = rows[i].natural and "#43D97F" or "#FFFFFF" } }
        end
        pub("bnd_pf_best", best)
        pub("bnd_pf_pitch", pr ~= nil)
        if not pr then page = 1; pub("bnd_pf_page", page) end
      end
  
      local function publishAttributes()
        for c, groups in ipairs(COLS) do
          local rows = {}
          for _, g in ipairs(groups) do
            local grp = P.groups[g]
            local dim = g == GK_GROUP and not P.isGK
            rows[#rows + 1] = { data = { hdr = true, label = grp.name, v = "", vc = "#FFFFFF", d = "", dc = "#FFFFFF", dir = 0, dim = dim } }
            for _, a in ipairs(grp.attrs) do
              rows[#rows + 1] = { data = { hdr = false, label = a.label, v = tostring(a.value), vc = PP.tierColor(a.value),
                                           d = PP.deltaText(a.delta), dc = PP.deltaColor(a.delta), dir = PP.deltaDir(a.delta), dim = dim } }
            end
          end
          pub("bnd_pf_col" .. c, rows)
        end
        pub("bnd_pf_tracked", P.deltas == true)
      end
  
      local function publishStats()
        local st = P.stats
        local function put(prefix, t)
          pub(prefix .. "_apps", t and tostring(t.apps) or "-")
          pub(prefix .. "_goals", t and tostring(t.goals) or "-")
          pub(prefix .. "_assists", t and tostring(t.assists) or "-")
          pub(prefix .. "_motm", t and tostring(t.motm) or "-")
        end
        put("bnd_pf_s", st.season)
        put("bnd_pf_c", st.career)
        local rows = {}
        for i, h in ipairs(st.history) do
          rows[i] = { data = { label = h.label, ovr = tostring(h.ovr), d = PP.deltaText(h.delta), dc = PP.deltaColor(h.delta), dir = PP.deltaDir(h.delta),
                               p = bar(h.ovr, 30, 99), now = h.now == true } }
        end
        pub("bnd_pf_hist", rows)
        -- this season per competition (the stock's tables, by league id): the first three and a total of all of them
        local comps, crow, ta, tg, tas = PP.comps and PP.comps(P.id, sp.loc) or {}, {}, 0, 0, 0
        for i, c in ipairs(comps) do
          if i <= 3 then crow[#crow + 1] = { data = { name = c.name, apps = tostring(c.apps), goals = tostring(c.goals), assists = tostring(c.assists), total = false } } end
          ta, tg, tas = ta + c.apps, tg + c.goals, tas + c.assists
        end
        if #comps > 1 then crow[#crow + 1] = { data = { name = "Total", apps = tostring(ta), goals = tostring(tg), assists = tostring(tas), total = true } } end
        pub("bnd_pf_comp", crow)
        pub("bnd_pf_note", P.tracked and "" or "This player is not followed by the career yet: his values are the database's.")
      end
  
      local function show3d()
        if tab == 1 and P then PP.show3d(P.id, P.clubId, P.isGK) end
      end
  
      local function load()
        P = PP.get(ids[idx], sp.teamId, opts)
        pub("bnd_pf_count", idx .. " / " .. n)
        pub("bnd_pf_multi", n > 1)
        if not P then pub("bnd_pf_name", "Player not found"); return end
        pub("bnd_pf_3d", rawget(_G, "F16_SVC") ~= nil)
        publishOverview()
        publishPitch()
        publishAttributes()
        publishStats()
        show3d()
      end
  
      local function step(by)
        if n < 2 then return end
        idx = (idx - 1 + by) % n + 1
        load()
      end
      H.act_pf_prev = function() step(-1) end
      H.act_pf_next = function() step(1) end
      for k = 1, 2 do
        H["act_pf_pg" .. k] = function()
          if not (P and P.posRatings) or page == k then return end
          page = k
          pub("bnd_pf_page", page)
        end
      end
      for k = 1, 3 do
        H["act_pf_tab" .. k] = function()
          if tab == k then return end
          tab = k
          pub("bnd_pf_tab", tab)
          if tab == 1 then show3d() else PP.hide3d(true) end
        end
      end
      load()
      return true
    end }
  end
  
  --[[ Training screen (R98e).
  
  PrismTraining.open (src/career/PrismTraining.lua, the hub's Training card) opens it. Two pages:
    1 the session   five slot cards (player, area, overall with the development arrow, the last session's grade and what it
                    gave, how many sessions and points training has given him so far); "Edit Slot" under the selected card,
                    Simulate Training (once a career week), Clear Slot and Back in the footer
    2 edit slot     the squad (position, face, name, overall and arrow, injured mark, the slot a player is already in) to
                    pick the slot's player from, and the six areas to pick what he works on (goalkeeping for keepers only);
                    Done goes back to the cards
  Everything is read and changed live through PrismTraining (the state is PlayerDev's, saved with the career). Back closes
  the screen and answers 0.
  ]]
  do
    local NS, NAREA, NROWS = 5, 6, 6   -- slots, areas, progress bars per slot (an area trains 5 or 6 attributes)
    local GRADE_COLOR = { ["A+"] = "#43D97F", A = "#7FE08A", B = "#A6E35C", C = "#F2C94C", D = "#F2A43A", E = "#F0504F" }
  
    MODES.training = { on = "bnd_trn_on", run = function(s, o, sp, pub)
      local TR = rawget(_G, "PrismTraining")
      local PP = rawget(_G, "PrismProfile")
      local H = s.handlers
      local answer = answerOnce(o)
      local page, sel = 1, 1
      local squad, byId, slots = {}, {}, {}
      local hintNow = str(sp.hint)
  
      -- an attribute's label, translated on its own in a language build (the gains line joins several of them)
      local function label(n)
        local l = (PP and PP.LABEL and PP.LABEL[n]) or n
        local I = rawget(_G, "PRISM_I18N")
        if type(I) == "table" and type(I.tr) == "function" then local ok, t = pcall(I.tr, l); if ok and t then l = t end end
        return l
      end
      local function gainsText(r)
        if not r then return "" end
        if r.skip == "injured" then return "Injured: sat out the session" end
        if r.skip then return "Not trained" end
        local parts, names = {}, {}
        for n in pairs(r.gains or {}) do names[#names + 1] = n end
        table.sort(names)
        for _, n in ipairs(names) do parts[#parts + 1] = "+" .. r.gains[n] .. " " .. label(n) end
        if #parts > 0 then return table.concat(parts, ", ") end
        if r.grade == "D" or r.grade == "E" then return "No progress this week" end
        return "Progress banked towards the next point"
      end
  
      local function refresh()
        if not TR then return end
        squad = TR.squad()
        byId = {}
        for _, p in ipairs(squad) do byId[p.id] = p end
        slots = TR.slots()
        local avail, nextDay = TR.available()
        local any = false
        for k = 1, NS do if slots[k] then any = true end end
        pub("bnd_trn_title", str(sp.title or "Training"))
        pub("bnd_trn_avail", avail and any)
        pub("bnd_trn_next", avail and "Session ready this week" or ("Next session: " .. str(nextDay)))
        pub("bnd_trn_hint", hintNow)
        for k = 1, NS do
          local sl = slots[k]
          local p = sl and byId[sl.id]
          pub("bnd_trn_vis" .. k, true)
          pub("bnd_trn_used" .. k, sl ~= nil)
          pub("bnd_trn_name" .. k, sl and str(p and p.short or ("#" .. sl.id)) or "Empty Slot")
          pub("bnd_trn_sub" .. k, sl and str(sl.label) or ("Slot " .. k))
          pub("bnd_trn_head" .. k, sl and { name = "$Head", id = sl.id } or {})
          pub("bnd_trn_pos" .. k, p and str(p.pos) or "")
          pub("bnd_trn_ovr" .. k, p and str(p.ovr) or "")
          pub("bnd_trn_dir" .. k, p and (p.dir or 0) or 0)
          pub("bnd_trn_area" .. k, sl and sl.area or "")
          local r = sl and sl.last
          pub("bnd_trn_grade" .. k, (r and r.grade) or "")
          pub("bnd_trn_gradec" .. k, (r and r.grade and GRADE_COLOR[r.grade]) or "#FFFFFF")
          pub("bnd_trn_gains" .. k, gainsText(r))
          pub("bnd_trn_inj" .. k, p and p.injured or false)
          -- the progress bars: each attribute the slot trains, its value, how far it is towards the next point, and what
          -- training has given it ("MAX" at its ceiling)
          local rows = sl and TR.rows and TR.rows(sl.id, sl.area) or {}
          for j = 1, NROWS do
            local r, b = rows[j], k .. "_" .. j
            pub("bnd_trn_an" .. b, r and label(r.name) or "")
            pub("bnd_trn_av" .. b, r and tostring(r.value) or "")
            pub("bnd_trn_ap" .. b, r and r.prog or 0)
            pub("bnd_trn_am" .. b, r and r.atMax == true or false)
            pub("bnd_trn_ag" .. b, r and (r.atMax and "MAX" or ((r.gained or 0) > 0 and ("+" .. r.gained) or "")) or "")
          end
          local n = sl and (sl.sessions or 0) or 0
          pub("bnd_trn_tot" .. k, sl and ((n == 1 and "1 session" or (tostring(n) .. " sessions")) .. "  \194\183  +" .. tostring(sl.gained or 0)) or "")
        end
        pub("bnd_trn_sel", sel)
        pub("bnd_trn_selused", slots[sel] ~= nil)
        -- the edit page: the squad (who is in which slot) and the selected slot's player and area
        local inSlot = {}
        for k = 1, NS do if slots[k] then inSlot[slots[k].id] = k end end
        local rows = {}
        local cur = slots[sel]
        for i, p in ipairs(squad) do
          rows[i] = { data = { id = p.id, pos = str(p.pos), head = { name = "$Head", id = p.id }, name = str(p.name), ovr = str(p.ovr),
            dir = p.dir or 0, inj = p.injured == true, slot = inSlot[p.id] and ("#" .. inSlot[p.id]) or "",
            sel = cur ~= nil and cur.id == p.id } }
        end
        pub("bnd_trn_squad", rows)
        pub("bnd_trn_n", #rows)
        local cp = cur and byId[cur.id]
        pub("bnd_trn_eslot", "Slot " .. sel)
        pub("bnd_trn_ename", cur and str(cp and cp.name or ("#" .. cur.id)) or "No player yet: pick one from the squad")
        pub("bnd_trn_earea", cur and cur.area or "")
        -- an area the slot's player may train: any, except goalkeeping, which is for keepers only
        for i, a in ipairs(TR.AREAS) do
          pub("bnd_trn_aok" .. i, cur ~= nil and (a.key ~= "goalkeeping" or (cp ~= nil and cp.gk == true)))
        end
        pub("bnd_trn_page", page)
      end
  
      local function setHint(h) hintNow = str(h or sp.hint); pub("bnd_trn_hint", hintNow) end
      -- players who left the club (or all of them, after a move to a new club) are out of their slots before anything shows
      if TR and TR.prune then
        local n, newClub = TR.prune(TR.squad())
        if newClub then hintNow = "New club: the training slots are free again."
        elseif n == 1 then hintNow = "A player left the club: his training slot is free."
        elseif n > 1 then hintNow = n .. " players left the club: their training slots are free." end
      end
      for k = 1, NS do H["act_trn" .. k] = function() sel = k; refresh() end end
      H.act_trn_go = function() page = 2; setHint("Pick a player for slot " .. sel .. ", then what he works on."); refresh() end
      H.act_trn_done = function() page = 1; setHint(sp.hint); refresh() end
      H.act_trn_clear = function()
        if TR and slots[sel] then TR.clear(sel); setHint("Slot " .. sel .. " is free.") end
        refresh()
      end
      H.act_trn_pick = function(_, d)
        local i = d and tonumber(d.id)
        local p = i and squad[i + 1]
        if not (TR and p) then return end
        if TR.setPlayer(sel, p.id) then
          setHint(p.name .. " trains in slot " .. sel .. (p.injured and ". He is injured: he sits out until he is fit." or "."))
        end
        refresh()
      end
      for i = 1, NAREA do
        H["act_trn_area" .. i] = function()
          local a = TR and TR.AREAS[i]
          if not (a and slots[sel]) then return end
          if TR.setArea(sel, a.key) then setHint("Slot " .. sel .. ": " .. a.label .. ".")
          else setHint("Goalkeeping is for goalkeepers only.") end
          refresh()
        end
      end
      H.act_trn_run = function()
        if not TR then return end
        local res, why = TR.run()
        if res then
          local parts = { "Session done: " .. res.trained .. " trained" }
          if res.skipped > 0 then parts[#parts + 1] = res.skipped .. " sat out injured" end
          parts[#parts + 1] = res.gained .. " attribute points gained"
          setHint(table.concat(parts, ", ") .. ".")
        elseif why == "done" then setHint("This week's session is done. Come back next week.")
        elseif why == "empty" then setHint("Put at least one player in a slot first.")
        else setHint("Training needs a career in progress.") end
        refresh()
      end
      H.act_trn_back = function() answer(0) end
      refresh()
      return true
    end }
  end
  
  --[[ Popup.model.lua - the model of the shared Popup overlay (src/skins/Popup.skin.js).
  
  Joined after src/models/popup/*.lua (see modes.lua). For an ordinary FCPopup message every mode's `on` binding is false
  and the stock FC modal shows. When the opener passed a screen (popupData.<mode>), that mode's binding is true and its
  run() publishes the screen and installs its handlers.
  ]]
  return function(s, o, init)
    if type(o) ~= "table" then return false end
    local data = type(o.data) == "table" and o.data or {}
    local function pub(b, v) s:onPublish(b, v) end
    local active
    for _, name in ipairs(MODE_ORDER) do
      if not active and MODES[name] and type(data[name]) == "table" then active = name end
    end
    for _, name in ipairs(MODE_ORDER) do
      local m = MODES[name]
      if m then pub(m.on, name == active) end
    end
    if not active then return true end
    return MODES[active].run(s, o, data[active], pub)
  end
end)()
return spec
